// Command notes serves the notes API.
//
// Usage: notes <port>
//
// It listens on 127.0.0.1:<port> and keeps its data in the SQLite database named by $NOTES_DB.
package main

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"syscall"
	"time"

	"notes/internal/server"
	"notes/internal/store"
)

func main() {
	log := slog.New(slog.NewTextHandler(os.Stderr, nil))
	if err := run(log, os.Args[1:]); err != nil {
		log.Error("fatal", "err", err)
		os.Exit(1)
	}
}

func run(log *slog.Logger, args []string) error {
	if len(args) != 1 {
		return errors.New("usage: notes <port>")
	}
	port, err := strconv.ParseUint(args[0], 10, 16)
	if err != nil || port == 0 {
		return fmt.Errorf("invalid port %q", args[0])
	}
	dbPath := os.Getenv("NOTES_DB")
	if dbPath == "" {
		return errors.New("NOTES_DB is not set")
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	st, err := store.Open(ctx, dbPath)
	if err != nil {
		return err
	}
	defer st.Close()

	addr := net.JoinHostPort("127.0.0.1", strconv.FormatUint(port, 10))
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		return err
	}
	srv := &http.Server{
		Handler:           server.New(st, log),
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       30 * time.Second,
		WriteTimeout:      30 * time.Second,
		IdleTimeout:       2 * time.Minute,
	}

	errc := make(chan error, 1)
	go func() { errc <- srv.Serve(ln) }()
	log.Info("listening", "addr", addr, "db", dbPath)

	select {
	case err := <-errc:
		return err
	case <-ctx.Done():
	}
	log.Info("shutting down")
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	return srv.Shutdown(shutdownCtx)
}

// Package note defines the note domain type and the rules a note's content must satisfy.
package note

import (
	"fmt"
	"slices"
	"strings"
	"unicode/utf8"
)

// Limits on note content.
const (
	MaxTitleLen = 200
	MaxTagLen   = 32
)

// Note is a stored note.
type Note struct {
	ID    int64    `json:"id"`
	Title string   `json:"title"`
	Body  string   `json:"body"`
	Tags  []string `json:"tags"`
}

// Input is the client-supplied content of a note, as accepted on create and on full replacement.
type Input struct {
	Title string
	Body  string
	Tags  []string
}

// ValidationError reports note content that breaks the rules. Its message is safe to show to clients.
type ValidationError struct {
	msg string
}

func (e *ValidationError) Error() string { return e.msg }

func invalid(format string, args ...any) error {
	return &ValidationError{msg: fmt.Sprintf(format, args...)}
}

// Normalize returns the canonical form of in: the title without leading and trailing whitespace, and the
// tags deduplicated and sorted ascending (never nil). It returns a *ValidationError if the result is invalid.
func (in Input) Normalize() (Input, error) {
	title := strings.TrimSpace(in.Title)
	if n := utf8.RuneCountInString(title); n < 1 || n > MaxTitleLen {
		return Input{}, invalid("title must be 1 to %d characters", MaxTitleLen)
	}
	tags := make([]string, 0, len(in.Tags))
	for _, t := range in.Tags {
		if !ValidTag(t) {
			return Input{}, invalid("invalid tag %q: must be 1 to %d characters from a-z, 0-9 and -", t, MaxTagLen)
		}
		tags = append(tags, t)
	}
	slices.Sort(tags)
	return Input{Title: title, Body: in.Body, Tags: slices.Compact(tags)}, nil
}

// ValidTag reports whether t is a well-formed tag: 1 to MaxTagLen characters from a-z, 0-9 and -.
func ValidTag(t string) bool {
	if len(t) < 1 || len(t) > MaxTagLen {
		return false
	}
	for i := 0; i < len(t); i++ {
		c := t[i]
		if (c < 'a' || c > 'z') && (c < '0' || c > '9') && c != '-' {
			return false
		}
	}
	return true
}

package note

import (
	"errors"
	"slices"
	"strings"
	"testing"
)

func TestNormalize(t *testing.T) {
	got, err := Input{Title: "  hi  ", Body: "b", Tags: []string{"work", "b-2", "work"}}.Normalize()
	if err != nil {
		t.Fatalf("Normalize: %v", err)
	}
	want := Input{Title: "hi", Body: "b", Tags: []string{"b-2", "work"}}
	if got.Title != want.Title || got.Body != want.Body || !slices.Equal(got.Tags, want.Tags) {
		t.Errorf("Normalize = %+v, want %+v", got, want)
	}
}

func TestNormalizeNilTags(t *testing.T) {
	got, err := Input{Title: "x"}.Normalize()
	if err != nil {
		t.Fatalf("Normalize: %v", err)
	}
	if got.Tags == nil || len(got.Tags) != 0 {
		t.Errorf("Tags = %#v, want empty non-nil slice", got.Tags)
	}
}

func TestNormalizeErrors(t *testing.T) {
	tests := []struct {
		name string
		in   Input
	}{
		{"empty title", Input{Title: ""}},
		{"blank title", Input{Title: "   "}},
		{"long title", Input{Title: strings.Repeat("é", MaxTitleLen+1)}},
		{"uppercase tag", Input{Title: "x", Tags: []string{"Bad"}}},
		{"empty tag", Input{Title: "x", Tags: []string{""}}},
		{"long tag", Input{Title: "x", Tags: []string{strings.Repeat("a", MaxTagLen+1)}}},
		{"space in tag", Input{Title: "x", Tags: []string{"a b"}}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			_, err := tt.in.Normalize()
			var verr *ValidationError
			if !errors.As(err, &verr) {
				t.Fatalf("Normalize error = %v, want *ValidationError", err)
			}
		})
	}
}

func TestNormalizeLimits(t *testing.T) {
	in := Input{Title: strings.Repeat("é", MaxTitleLen), Tags: []string{strings.Repeat("a", MaxTagLen), "0-9"}}
	if _, err := in.Normalize(); err != nil {
		t.Errorf("Normalize at limits: %v", err)
	}
}

package server

import "net/http"

// handleReplaceNote serves PUT /notes/{id}: a full replacement, so an omitted body or tags becomes "" or [].
func (s *Server) handleReplaceNote(w http.ResponseWriter, r *http.Request) {
	id, ok := noteID(r)
	if !ok {
		s.writeNotFound(w)
		return
	}
	in, err := decodeNoteInput(w, r)
	if err != nil {
		s.writeErr(w, r, err)
		return
	}
	n, err := s.store.Replace(r.Context(), id, in)
	if err != nil {
		s.writeErr(w, r, err)
		return
	}
	s.writeJSON(w, http.StatusOK, n)
}

// handleDeleteNote serves DELETE /notes/{id}.
func (s *Server) handleDeleteNote(w http.ResponseWriter, r *http.Request) {
	id, ok := noteID(r)
	if !ok {
		s.writeNotFound(w)
		return
	}
	if err := s.store.Delete(r.Context(), id); err != nil {
		s.writeErr(w, r, err)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

package server

import (
	"net/http"
	"testing"

	"notes/internal/note"
)

func TestReplaceNote(t *testing.T) {
	s := newTestServer(t)
	mustCreate(t, s, `{"title":"old","body":"text","tags":["x"]}`)

	want := note.Note{ID: 1, Title: "new", Body: "", Tags: []string{"a", "b"}}
	rec := do(t, s, http.MethodPut, "/notes/1", `{"title":"  new ","tags":["b","a","b"]}`)
	wantStatus(t, rec, http.StatusOK)
	wantJSON(t, rec, want)

	rec = do(t, s, http.MethodGet, "/notes/1", "")
	wantStatus(t, rec, http.StatusOK)
	wantJSON(t, rec, want)

	// Omitted (or null) body and tags are reset, not kept.
	rec = do(t, s, http.MethodPut, "/notes/1", `{"title":"t","body":null,"tags":null}`)
	wantStatus(t, rec, http.StatusOK)
	wantJSON(t, rec, note.Note{ID: 1, Title: "t", Body: "", Tags: []string{}})
}

func TestReplaceNoteErrors(t *testing.T) {
	s := newTestServer(t)
	orig := mustCreate(t, s, `{"title":"keep","body":"b","tags":["k"]}`)

	for _, body := range []string{
		``, `{`, `[]`, `null`, `{}`, `{"title":""}`, `{"title":"  "}`, `{"title":1}`,
		`{"title":"x","body":2}`, `{"title":"x","tags":"a"}`, `{"title":"x","tags":["A"]}`,
	} {
		t.Run(body, func(t *testing.T) {
			wantError(t, do(t, s, http.MethodPut, "/notes/1", body), http.StatusBadRequest)
		})
	}
	// Failed replacements leave the note untouched.
	rec := do(t, s, http.MethodGet, "/notes/1", "")
	wantStatus(t, rec, http.StatusOK)
	wantJSON(t, rec, orig)

	for _, path := range []string{"/notes/9", "/notes/0", "/notes/-1", "/notes/abc"} {
		t.Run(path, func(t *testing.T) {
			wantError(t, do(t, s, http.MethodPut, path, `{"title":"none"}`), http.StatusNotFound)
		})
	}
}

func TestDeleteNote(t *testing.T) {
	s := newTestServer(t)
	mustCreate(t, s, `{"title":"a"}`)
	mustCreate(t, s, `{"title":"b"}`)

	rec := do(t, s, http.MethodDelete, "/notes/2", "")
	wantStatus(t, rec, http.StatusNoContent)
	if rec.Body.Len() != 0 {
		t.Errorf("body = %q, want empty", rec.Body.String())
	}
	wantError(t, do(t, s, http.MethodGet, "/notes/2", ""), http.StatusNotFound)
	wantError(t, do(t, s, http.MethodDelete, "/notes/2", ""), http.StatusNotFound)
	wantError(t, do(t, s, http.MethodPut, "/notes/2", `{"title":"x"}`), http.StatusNotFound)
	wantStatus(t, do(t, s, http.MethodGet, "/notes/1", ""), http.StatusOK)

	for _, path := range []string{"/notes/0", "/notes/-1", "/notes/abc", "/notes/99"} {
		t.Run(path, func(t *testing.T) {
			wantError(t, do(t, s, http.MethodDelete, path, ""), http.StatusNotFound)
		})
	}

	// The id of a deleted note is not reused.
	if n := mustCreate(t, s, `{"title":"c"}`); n.ID != 3 {
		t.Errorf("id after delete = %d, want 3", n.ID)
	}
}

