package server

import (
	"encoding/json"
	"io"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"reflect"
	"strings"
	"testing"

	"notes/internal/note"
	"notes/internal/store"
)

// newTestServer returns a Server backed by a fresh database that is removed when the test ends.
func newTestServer(t *testing.T) *Server {
	t.Helper()
	st, err := store.Open(t.Context(), filepath.Join(t.TempDir(), "notes.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { st.Close() })
	return New(st, slog.New(slog.NewTextHandler(io.Discard, nil)))
}

// do sends a request with the given body ("" for none) and returns the recorded response.
func do(t *testing.T, s *Server, method, path, body string) *httptest.ResponseRecorder {
	t.Helper()
	var r io.Reader
	if body != "" {
		r = strings.NewReader(body)
	}
	req := httptest.NewRequestWithContext(t.Context(), method, path, r)
	if body != "" {
		req.Header.Set("Content-Type", "application/json")
	}
	rec := httptest.NewRecorder()
	s.ServeHTTP(rec, req)
	return rec
}

// wantStatus fails the test if rec does not have the given status.
func wantStatus(t *testing.T, rec *httptest.ResponseRecorder, status int) {
	t.Helper()
	if rec.Code != status {
		t.Fatalf("status = %d, want %d (body %q)", rec.Code, status, rec.Body.String())
	}
}

// wantJSON fails the test if rec is not a JSON response equal to want, which is decoded into a value of
// the same type as want.
func wantJSON[T any](t *testing.T, rec *httptest.ResponseRecorder, want T) {
	t.Helper()
	if ct := rec.Header().Get("Content-Type"); ct != "application/json" {
		t.Errorf("Content-Type = %q, want application/json", ct)
	}
	var got T
	if err := json.Unmarshal(rec.Body.Bytes(), &got); err != nil {
		t.Fatalf("decode %q: %v", rec.Body.String(), err)
	}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("body = %+v, want %+v", got, want)
	}
}

// wantError fails the test unless rec has the given status and a JSON {"error": ...} body.
func wantError(t *testing.T, rec *httptest.ResponseRecorder, status int) {
	t.Helper()
	wantStatus(t, rec, status)
	var body errorBody
	if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil || body.Error == "" {
		t.Errorf("error body = %q, want {\"error\": <message>}", rec.Body.String())
	}
}

// mustCreate creates a note through the API and returns it.
func mustCreate(t *testing.T, s *Server, body string) note.Note {
	t.Helper()
	rec := do(t, s, http.MethodPost, "/notes", body)
	wantStatus(t, rec, http.StatusCreated)
	var n note.Note
	if err := json.Unmarshal(rec.Body.Bytes(), &n); err != nil {
		t.Fatalf("decode created note %q: %v", rec.Body.String(), err)
	}
	return n
}

package server

import (
	"errors"
	"net/http"
	"net/url"
	"strconv"

	"notes/internal/note"
	"notes/internal/store"
)

// listResponse is the JSON body of GET /notes.
type listResponse struct {
	Notes []note.Note `json:"notes"`
}

// handleListNotes serves GET /notes.
func (s *Server) handleListNotes(w http.ResponseWriter, r *http.Request) {
	f, err := parseFilter(r.URL.Query())
	if err != nil {
		s.writeErr(w, r, err)
		return
	}
	notes, err := s.store.List(r.Context(), f)
	if err != nil {
		s.writeErr(w, r, err)
		return
	}
	s.writeJSON(w, http.StatusOK, listResponse{Notes: notes})
}

// parseFilter reads the tag, q, after and limit query parameters. Its errors are *requestError.
func parseFilter(q url.Values) (store.Filter, error) {
	f := store.Filter{Limit: store.MaxListLimit}
	if q.Has("tag") {
		tag := q.Get("tag")
		f.Tag = &tag
	}
	if q.Has("q") {
		text := q.Get("q")
		f.Query = &text
	}
	if q.Has("after") {
		after, err := strconv.ParseInt(q.Get("after"), 10, 64)
		// An integer beyond the int64 range is still a valid bound: ParseInt clamps it, which keeps
		// every note (very negative) or none (very positive).
		if err != nil && !errors.Is(err, strconv.ErrRange) {
			return store.Filter{}, badRequest("after must be an integer")
		}
		f.After = after
	}
	if q.Has("limit") {
		limit, err := strconv.Atoi(q.Get("limit"))
		if err != nil || limit < 1 || limit > store.MaxListLimit {
			return store.Filter{}, badRequest("limit must be an integer from 1 to %d", store.MaxListLimit)
		}
		f.Limit = limit
	}
	return f, nil
}

package server

import (
	"net/http"
	"testing"

	"notes/internal/note"
)

func TestListNotes(t *testing.T) {
	s := newTestServer(t)

	rec := do(t, s, http.MethodGet, "/notes", "")
	wantStatus(t, rec, http.StatusOK)
	wantJSON(t, rec, listResponse{Notes: []note.Note{}})
	if got := rec.Body.String(); got != "{\"notes\":[]}\n" {
		t.Errorf("empty list body = %q, want {\"notes\":[]}", got)
	}

	a := mustCreate(t, s, `{"title":"Hello world","tags":["greet"]}`)
	b := mustCreate(t, s, `{"title":"shopping","body":"milk","tags":["misc"]}`)
	c := mustCreate(t, s, `{"title":"other","body":"HELLO there","tags":["misc"]}`)

	tests := []struct {
		path string
		want []note.Note
	}{
		{"/notes", []note.Note{a, b, c}},
		{"/notes?tag=misc", []note.Note{b, c}},
		{"/notes?tag=Misc", []note.Note{}},
		{"/notes?q=hello", []note.Note{a, c}},
		{"/notes?q=HELLO%20W", []note.Note{a}},
		{"/notes?q=hello&tag=misc", []note.Note{c}},
		{"/notes?after=1", []note.Note{b, c}},
		{"/notes?after=0", []note.Note{a, b, c}},
		{"/notes?after=-1", []note.Note{a, b, c}},
		{"/notes?after=99999999999999999999", []note.Note{}},
		{"/notes?after=-99999999999999999999", []note.Note{a, b, c}},
		{"/notes?limit=2", []note.Note{a, b}},
		{"/notes?limit=100", []note.Note{a, b, c}},
		{"/notes?after=1&limit=1", []note.Note{b}},
		{"/notes?tag=misc&q=o&after=2&limit=1", []note.Note{c}},
	}
	for _, tt := range tests {
		t.Run(tt.path, func(t *testing.T) {
			rec := do(t, s, http.MethodGet, tt.path, "")
			wantStatus(t, rec, http.StatusOK)
			wantJSON(t, rec, listResponse{Notes: tt.want})
		})
	}
}

func TestListNotesErrors(t *testing.T) {
	s := newTestServer(t)
	mustCreate(t, s, `{"title":"x"}`)
	for _, query := range []string{
		"limit=0", "limit=101", "limit=-1", "limit=abc", "limit=", "limit=1.5", "limit=99999999999999999999",
		"after=abc", "after=", "after=1.5", "after=1e3",
	} {
		t.Run(query, func(t *testing.T) {
			wantError(t, do(t, s, http.MethodGet, "/notes?"+query, ""), http.StatusBadRequest)
		})
	}
}

package server

import (
	"net/http"

	"notes/internal/note"
)

// noteRequest is the JSON body of POST /notes and PUT /notes/{id}. Pointers tell an omitted (or null)
// field from an empty one.
type noteRequest struct {
	Title *string   `json:"title"`
	Body  *string   `json:"body"`
	Tags  *[]string `json:"tags"`
}

// decodeNoteInput reads and normalizes a note body. An omitted body or tags field becomes "" or []. Its
// errors (*requestError or *note.ValidationError) are answered with 400 by writeErr.
func decodeNoteInput(w http.ResponseWriter, r *http.Request) (note.Input, error) {
	var req noteRequest
	if err := decodeJSON(w, r, &req); err != nil {
		return note.Input{}, err
	}
	return req.input().Normalize()
}

func (req noteRequest) input() note.Input {
	var in note.Input
	if req.Title != nil {
		in.Title = *req.Title
	}
	if req.Body != nil {
		in.Body = *req.Body
	}
	if req.Tags != nil {
		in.Tags = *req.Tags
	}
	return in
}

func (s *Server) handleCreateNote(w http.ResponseWriter, r *http.Request) {
	in, err := decodeNoteInput(w, r)
	if err != nil {
		s.writeErr(w, r, err)
		return
	}
	n, err := s.store.Create(r.Context(), in)
	if err != nil {
		s.writeErr(w, r, err)
		return
	}
	s.writeJSON(w, http.StatusCreated, n)
}

func (s *Server) handleGetNote(w http.ResponseWriter, r *http.Request) {
	id, ok := noteID(r)
	if !ok {
		s.writeNotFound(w)
		return
	}
	n, err := s.store.Get(r.Context(), id)
	if err != nil {
		s.writeErr(w, r, err)
		return
	}
	s.writeJSON(w, http.StatusOK, n)
}

package server

import (
	"net/http"
	"strings"
	"testing"

	"notes/internal/note"
)

func TestHealth(t *testing.T) {
	s := newTestServer(t)
	rec := do(t, s, http.MethodGet, "/health", "")
	wantStatus(t, rec, http.StatusOK)
	if got := rec.Body.String(); got != "ok" {
		t.Errorf("body = %q, want ok", got)
	}
}

func TestCreateAndGet(t *testing.T) {
	s := newTestServer(t)

	rec := do(t, s, http.MethodPost, "/notes", `{"title":"first"}`)
	wantStatus(t, rec, http.StatusCreated)
	wantJSON(t, rec, note.Note{ID: 1, Title: "first", Body: "", Tags: []string{}})

	second := note.Note{ID: 2, Title: "second", Body: "some text", Tags: []string{"b-2", "work"}}
	rec = do(t, s, http.MethodPost, "/notes",
		`{"title":"  second  ","body":"some text","tags":["work","b-2","work"],"extra":1}`)
	wantStatus(t, rec, http.StatusCreated)
	wantJSON(t, rec, second)

	rec = do(t, s, http.MethodGet, "/notes/2", "")
	wantStatus(t, rec, http.StatusOK)
	wantJSON(t, rec, second)
}

func TestCreateNullOptionalFields(t *testing.T) {
	s := newTestServer(t)
	rec := do(t, s, http.MethodPost, "/notes", `{"title":"x","body":null,"tags":null}`)
	wantStatus(t, rec, http.StatusCreated)
	wantJSON(t, rec, note.Note{ID: 1, Title: "x", Body: "", Tags: []string{}})
}

func TestCreateErrors(t *testing.T) {
	tests := []struct {
		name, body string
	}{
		{"empty body", ``},
		{"truncated JSON", `{"title": `},
		{"trailing data", `{"title":"x"} {}`},
		{"array", `[]`},
		{"string", `"x"`},
		{"null", `null`},
		{"missing title", `{}`},
		{"null title", `{"title":null}`},
		{"blank title", `{"title":"   "}`},
		{"long title", `{"title":"` + strings.Repeat("a", note.MaxTitleLen+1) + `"}`},
		{"numeric title", `{"title":5}`},
		{"numeric body", `{"title":"x","body":3}`},
		{"tags not array", `{"title":"x","tags":"a"}`},
		{"numeric tag", `{"title":"x","tags":[1]}`},
		{"uppercase tag", `{"title":"x","tags":["Bad"]}`},
		{"empty tag", `{"title":"x","tags":[""]}`},
	}
	s := newTestServer(t)
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			wantError(t, do(t, s, http.MethodPost, "/notes", tt.body), http.StatusBadRequest)
		})
	}
	// Nothing was stored, so the next note still gets id 1.
	if n := mustCreate(t, s, `{"title":"ok"}`); n.ID != 1 {
		t.Errorf("id after failed creates = %d, want 1", n.ID)
	}
}

func TestGetNotFound(t *testing.T) {
	s := newTestServer(t)
	mustCreate(t, s, `{"title":"x"}`)
	for _, path := range []string{"/notes/abc", "/notes/0", "/notes/-1", "/notes/7", "/notes/99999999999999999999"} {
		t.Run(path, func(t *testing.T) {
