	first := mustCreate(t, s, "first")
	if want := (note.Note{ID: 1, Title: "first", Tags: []string{}}); !reflect.DeepEqual(first, want) {
		t.Errorf("Create = %+v, want %+v", first, want)
	}
	second, err := s.Create(ctx, note.Input{Title: "second", Body: "text", Tags: []string{"a", "b"}})
	if err != nil {
		t.Fatalf("Create: %v", err)
	}
	if second.ID != 2 {
		t.Errorf("second id = %d, want 2", second.ID)
	}

	for _, want := range []note.Note{first, second} {
		got, err := s.Get(ctx, want.ID)
		if err != nil {
			t.Fatalf("Get(%d): %v", want.ID, err)
		}
		if !reflect.DeepEqual(got, want) {
			t.Errorf("Get(%d) = %+v, want %+v", want.ID, got, want)
		}
	}
}

func TestGetNotFound(t *testing.T) {
	s, _ := openTest(t)
	if _, err := s.Get(t.Context(), 1); !errors.Is(err, ErrNotFound) {
		t.Errorf("Get on empty store: err = %v, want ErrNotFound", err)
	}
}

func TestPersistence(t *testing.T) {
	s, path := openTest(t)
	want := mustCreate(t, s, "kept", "x")
	if err := s.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}

	head, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.HasPrefix(head, []byte("SQLite format 3\x00")) {
		t.Errorf("%s is not a SQLite database", path)
	}

	s, err = Open(t.Context(), path)
	if err != nil {
		t.Fatalf("reopen: %v", err)
	}
	defer s.Close()
	got, err := s.Get(t.Context(), want.ID)
	if err != nil {
		t.Fatalf("Get after reopen: %v", err)
	}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("Get after reopen = %+v, want %+v", got, want)
	}
	if n := mustCreate(t, s, "next"); n.ID != want.ID+1 {
		t.Errorf("id after reopen = %d, want %d", n.ID, want.ID+1)
	}
}

func TestConcurrentCreate(t *testing.T) {
	s, _ := openTest(t)
	const n = 50
	ids := make(chan int64, n)
	var wg sync.WaitGroup
	for range n {
		wg.Go(func() {
			created, err := s.Create(t.Context(), note.Input{Title: "c", Tags: []string{"t"}})
			if err != nil {
				t.Errorf("Create: %v", err)
				return
			}
			ids <- created.ID
		})
	}
	wg.Wait()
	close(ids)
	seen := make(map[int64]bool)
	for id := range ids {
		if seen[id] || id < 1 || id > n {
			t.Errorf("unexpected id %d", id)
		}
		seen[id] = true
	}
	if len(seen) != n {
		t.Errorf("got %d distinct ids, want %d", len(seen), n)
	}
}

package store

import (
	"context"
	"database/sql"
	"fmt"
)

// TagCount is a tag and the number of notes that have it.
type TagCount struct {
	Tag   string `json:"tag"`
	Count int64  `json:"count"`
}

// Stats summarizes the store: the number of notes and, for each tag in use, the number of notes that have
// it.
type Stats struct {
	Notes int64
	Tags  []TagCount
}

// Stats returns the note count and the tag counts, both read from the same snapshot of the database.
// Tags are ordered as by TagCounts.
func (s *Store) Stats(ctx context.Context) (Stats, error) {
	var st Stats
	err := s.inReadTx(ctx, func(tx *sql.Tx) error {
		if err := tx.QueryRowContext(ctx, `SELECT count(*) FROM notes`).Scan(&st.Notes); err != nil {
			return fmt.Errorf("count notes: %w", err)
		}
		var err error
		st.Tags, err = tagCounts(ctx, tx)
		return err
	})
	if err != nil {
		return Stats{}, err
	}
	return st, nil
}

// TagCounts returns every tag in use with the number of notes that have it, ordered by count descending,
// then tag ascending. The result is never nil.
func (s *Store) TagCounts(ctx context.Context) ([]TagCount, error) {
	return tagCounts(ctx, s.db)
}

func tagCounts(ctx context.Context, q querier) ([]TagCount, error) {
	// Tags are removed with their note (ON DELETE CASCADE), so every row belongs to an existing note.
	rows, err := q.QueryContext(ctx,
		`SELECT tag, count(*) AS n FROM note_tags GROUP BY tag ORDER BY n DESC, tag ASC`)
	if err != nil {
		return nil, fmt.Errorf("count tags: %w", err)
	}
	defer rows.Close()
	counts := []TagCount{}
	for rows.Next() {
		var tc TagCount
		if err := rows.Scan(&tc.Tag, &tc.Count); err != nil {
			return nil, fmt.Errorf("count tags: %w", err)
		}
		counts = append(counts, tc)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("count tags: %w", err)
	}
	return counts, nil
}

// inReadTx runs fn in a read-only transaction, which sees a single consistent snapshot of the database
// without taking the write lock.
func (s *Store) inReadTx(ctx context.Context, fn func(tx *sql.Tx) error) error {
	tx, err := s.db.BeginTx(ctx, &sql.TxOptions{ReadOnly: true})
	if err != nil {
		return fmt.Errorf("begin read: %w", err)
	}
	defer tx.Rollback()
	return fn(tx)
}

